<template>
  <div class="full-width q-pa-md mobile-grid-text">
    <template
      v-for="(row, index) in table_data"
      :key="row['id']"
      :data-index="index"
    >
      <div class="row q-pb-sm">
        <div class="col-11">
          <div class="row">
            <div
              class="col-12 text-primary ellipsify rounded-borders solid-border"
              style="margin-top: 5px"
              @click="$emit('rowClick', row, true, false)"
            >
              <span class="q-pa-sm">{{ row['filename'] }}</span>
            </div>
          </div>
        </div>
        <div class="col-1">
          <q-icon
            name="expand_more"
            size="md"
            :id="'expand_more_' + index"
            @click="toggleDetails(index)"
          />
          <q-icon
            name="expand_less"
            size="md"
            class="hidden"
            :id="'expand_less_' + index"
            @click="toggleDetails(index)"
          />
        </div>

        <div class="col-4">{{ $t('type') }}:</div>
        <div class="col-8">
          {{ displayDocType(row['doc_type']) }}
        </div>

        <div class="col-4">{{ $t('status') }}:</div>
        <div class="col-8">
          {{ getLabelTranslation(row['status']) }}
        </div>
      </div>

      <div class="row hidden" :id="'details_block_' + index">
        <div class="col-4">{{ $t('pages_dash') }}:</div>
        <div class="col-8">
          {{ row['pages'] }}
        </div>

        <div class="col-4" v-if="row['quality']">{{ $t('quality') }}:</div>
        <div class="col-8" v-if="row['quality']">
          {{ row['quality'] }}
          <!-- <img width="20"  src="/images/document_quality.svg" class="black_to_white" />
                <q-tooltip v-if="row['quality']">
                    <div
                        class="row"
                        v-html="renderquality(row)"
                    ></div>
                </q-tooltip> -->
        </div>

        <div class="col-4">{{ $t('assigned_to') }}:</div>
        <div class="col-8">
          {{ row['assigned_to'] }}
        </div>

        <div class="col-4">{{ $t('last_saved_by') }}:</div>
        <div class="col-8">
          {{ row['last_saved_by'] }}
        </div>

        <div class="col-4">{{ $t('modified_at') }}:</div>
        <div class="col-8">
          {{ row['last_modified_on'] }}
        </div>

        <div class="col-4">{{ $t('imported_on') }}:</div>
        <div class="col-8">
          {{ row['created_on'] }}
        </div>
      </div>

      <!-- <div class="full-width border-bottom q-mt-sm q-mb-sm" ></div> -->
      <q-separator class="q-mt-sm q-mb-sm" />
    </template>
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { $ } from 'src/pages/assets';
import { defineComponent, ref } from 'vue';
import { useSettingStore } from 'src/store/main';
import docTypeLable from 'src/utils/docTypeLable';
import documentUtil from 'src/utils/documentUtil';

export default defineComponent({
  mixins: [docTypeLable, documentUtil],
  props: {
    table_data: {} as any,
  },

  //   components: {

  //   },
  //   mounted: function () {
  //     console.clear();
  //     logInfo(this.table_data);
  //   },
  //   unmounted: function () {
  //   },
  methods: {
    renderquality(row: any) {
      if (
        !this.user_settings['OCR_PERCENTAGE'] ||
        !this.user_settings['OCR_PERCENTAGE']
      ) {
        return;
      }

      let quality = '';
      if (row.hasOwnProperty('quality')) {
        let name = this.$t('overall');
        const item = row['quality'];
        if (
          parseInt(row['quality']) <
          parseInt(this.user_settings['OCR_PERCENTAGE'])
        ) {
          quality =
            name +
            ' : <FONT COLOR="#AA0500">' +
            row['quality'] +
            '</FONT COLOR>';
        }
        if (parseInt(item) == parseInt(this.user_settings['OCR_PERCENTAGE'])) {
          quality =
            name +
            ' : <FONT COLOR="#ffff00">' +
            row['quality'] +
            '</FONT COLOR>';
        }
        if (parseInt(item) > parseInt(this.user_settings['OCR_PERCENTAGE'])) {
          quality =
            name +
            ' : <FONT COLOR="#00ff00">' +
            row['quality'] +
            '</FONT COLOR>';
        }
      }

      return quality;
    },

    toggleDetails(index: number) {
      const expand_more = $('#expand_more_' + index) as HTMLElement;
      const expand_less = $('#expand_less_' + index) as HTMLElement;
      const details_block = $('#details_block_' + index) as HTMLElement;

      if (expand_more) {
        expand_more.classList.toggle('hidden');
      }

      if (expand_less) {
        expand_less.classList.toggle('hidden');
      }

      if (details_block) {
        details_block.classList.toggle('hidden');
      }
    },
  },
  setup() {
    const settings_store = useSettingStore();
    const { user_settings } = storeToRefs(settings_store);

    return {
      user_settings,
    };
  },
});
</script>
